export interface SMSFeature {
  id: string; // e.g. "TEN-001"
  moduleCode: string; // e.g. "TEN"
  moduleName: string;
  layer: 1 | 2 | 3 | 4 | 5 | 6;
  layerName: string;
  code: string; // "001"
  name: string;
  phase: 'P1' | 'P2' | 'P3' | 'P4';
  phaseName: string;
  priority: 'M' | 'S' | 'C'; // Must, Should, Could
  priorityName: 'Must Have' | 'Should Have' | 'Could Have';
  targetView: string;
  status: 'Implemented' | 'Live Ready' | 'Operational';
  description: string;
}

export interface SMSModule {
  id: string;
  code: string;
  number: number;
  name: string;
  layer: 1 | 2 | 3 | 4 | 5 | 6;
  layerName: string;
  count: number;
  targetView: string;
  icon: string;
  description: string;
}

